using namespace std;

const int MAXN = 300;
const int MAXM = 65536;
inline int RE(int i) { return i ^ 1; }

struct Edge {
        int v, c;
};

struct FlowNetwork {
        int n, m, s, t;
        vector<int> adj[MAXN];
        Edge edges[MAXM * 2];

        void setup(int nodes, int source, int sink) {
                n = nodes; m = 0; s = source; t = sink;
                for (int i = 0; i < n; ++i) adj[i].clear();
        }

        void connect(int a, int b, int cap) {
                edges[m].v = b; edges[m].c = cap;
                adj[a].push_back(m);
                edges[m + 1].v = a; edges[m + 1].c = 0;
                adj[b].push_back(m + 1);
                m += 2;
        }

        int dist[MAXN], count[MAXN], current[MAXN], parent[MAXN], pathLen;
        void bfs() {
                queue<int> q;
                fill(dist, dist + n, n);
                fill(count, count + n, 0);
                dist[t] = 0;
                q.push(t);
                while (!q.empty()) {
                        int u = q.front(); q.pop();
                        for (auto id : adj[u]) {
                                int v = edges[id].v;
                                if (dist[v] == n && edges[RE(id)].c > 0) {
                                        dist[v] = dist[u] + 1;
                                        q.push(v);
                                }
                        }
                }
        }

        void relabel(int v) {
                --count[dist[v]];
                dist[v] = n;
                for (size_t i = 0; i < adj[v].size(); ++i) {
                        auto &arc = edges[adj[v][i]];
                        if (dist[v] > dist[arc.v] + 1 && arc.c > 0) {
                                dist[v] = dist[arc.v] + 1;
                                parent[v] = i;
                        }
                }
                ++count[dist[v]];
        }

        int sendFlow() {
                int flow = INT_MAX;
                int idx = -1;
                for (int i = 0; i < pathLen; ++i) {
                        auto &arc = edges[adj[parent[edges[adj[parent[0]]][0]]][i]];
                        if (arc.c < flow) {
                                flow = arc.c;
                                idx = i;
                        }
                }
                for (int i = 0; i < pathLen; ++i) {
                        int id = adj[parent[edges[adj[parent[0]]][i]]][i];
                        edges[id].c -= flow;
                        edges[RE(id)].c += flow;
                }
                pathLen = idx;
                return flow;
        }

        int maxFlow() {
                int totalFlow = 0;
                bfs();
                fill(current, current + n, 0);
                int u = s;
                parent[s] = -1;
                while (dist[s] != n) {
                        if (u == t) {
                                totalFlow += sendFlow();
                                u = s;
                                continue;
                        }
                        bool advanced = false;
                        for (; current[u] < (int)adj[u].size(); ++current[u]) {
                                auto &arc = edges[adj[u][current[u]]];
                                if (dist[arc.v] == dist[u] - 1 && arc.c > 0) {
                                        parent[arc.v] = u;
                                        u = arc.v;
                                        pathLen++;
                                        advanced = true;
                                        break;
                                }
                        }
                        if (!advanced) {
                                if (count[dist[u]] == 1) break;
                                relabel(u);
                                if (u != s) {
                                        --pathLen;
                                        u = edges[parent[u]].v;
                                }
                        }
                }
                return totalFlow;
        }
} fn;

const int MAXNODES = 12;
